const n=(tag,text)=>{const e=document.createElement(tag);if(text!=null)e.textContent=text;return e;};
const digest=async raw=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',raw))].map(x=>x.toString(16).padStart(2,'0')).join('');
export function signingBundleButton({origin,token,session,context,beforeDownload=async()=>true}){
 const button=n('button','서명용 파일');button.type='button';button.className='signing-bundle-button';let ready=null,busy=false;
 const save=()=>{const url=URL.createObjectURL(new Blob([ready.raw],{type:'application/pdf'})),a=n('a');a.href=url;a.download=ready.filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);};
 button.onclick=async()=>{if(ready&&ready.key===JSON.stringify(context())){save();return;}if(busy)return;busy=true;button.disabled=true;let note=button.nextElementSibling;if(!note?.classList.contains('signing-bundle-status')){note=n('small');note.className='signing-bundle-status';button.after(note);}try{if(!await beforeDownload())return;const c=context(),base='/safety-features/half-year-reviews/plans/'+encodeURIComponent(c.plan),q='?'+new URLSearchParams({period:c.period});const get=async path=>{session();const r=await fetch(origin+path,{cache:'no-store',headers:{Authorization:'Bearer '+token}});session();if(!r.ok)throw Error('파일을 확인하지 못했습니다. 다시 눌러 주세요.');return r;};const result=await(await get(base+'/weekly-pdf'+q)).json();if(!result.ready){note.textContent='서명용 파일은 월요일 새벽에 준비합니다.';return;}if(result.missing?.length&&!confirm(result.missing.map(r=>r.label).join(', ')+'이 아직입니다. 다운로드 받으시겠습니까?'))return;const raw=await(await get(base+'/signature-bundle/'+result.id+'/file'+q)).arrayBuffer();if(raw.byteLength!==result.result.bytes||await digest(raw)!==result.result.sha256)throw Error('파일을 다시 확인해 주세요.');ready={raw,filename:result.filename,key:JSON.stringify(c)};save();note.textContent='4종 평가서를 준비했습니다.';}catch(e){note.textContent=e.message;}finally{busy=false;button.disabled=false;button.textContent=ready?'PDF 다운로드':'서명용 파일';}};return button;
}
